  function equippedTool(actionId,snapshot=null){const id=snapshot?.[actionId]||B().equippedTools[actionId];return smithTool(id);}
  function toolFactor(t){if(!t)return 1;const pct=toolCondition(t.id)/Math.max(1,toolMax(t.id));return .68+.32*pct;}
