  function toolFailureReduction(r,snapshot=null){const list=r.actions.map(a=>equippedTool(a,snapshot)).filter(Boolean);return list.length?list.reduce((n,t)=>n+Number(t.failureReduction||0)*toolFactor(t),0)/list.length:0;}
  function toolEfficiency(r,snapshot=null){const list=r.actions.map(a=>equippedTool(a,snapshot)).filter(Boolean);return list.length?list.reduce((n,t)=>n+Math.max(.65,Number(t.efficiency||1)*toolFactor(t)),0)/list.length:1;}
