  function baseProperties(resourceId,q,alloyId='',defect=false){const a=alloyDef(alloyId),ap=a?.properties||{},steel=['steel_billet','steel_fittings','rare_steel_billet','rare_steel_fittings'].includes(resourceId),piece=['iron_nails','iron_fittings','steel_fittings','silver_mountings','rare_steel_fittings'].includes(resourceId);const props={hardness:34+q*.30+(steel?7:0),toughness:38+q*.34+(steel?4:0),regularity:30+q*.48+(piece?5:0),finish:28+q*.50+(piece?4:0),integrity:38+q*.48-(defect?12:0)};for(const [k,v] of Object.entries(ap))props[k]=Number(props[k]||50)+Number(v||0);for(const k of Object.keys(PROP_LABELS))props[k]=Math.round(clamp(props[k],5,100));return props;}
