  function treatmentAllowed(tr,lot){if(!tr||!lot||activeTask())return false;if(S().level<Number(tr.minLevel||1)||rankOrder()<Number(tr.minRank||0))return false;if(tr.requiresStation&&!stationBuilt(tr.requiresStation))return false;if(!(tr.allowed||[]).includes(lot.resourceId))return false;const done=lot.treatments||[];if(done.includes(tr.id))return false;if((tr.requires||[]).some(id=>!done.includes(id)))return false;if(C.resource('firewood')<Number(tr.firewood||0))return false;for(const [id,q] of Object.entries(tr.inputs||{}))if(C.resource(id)<Number(q||0))return false;return true;}
