  function skillProgress(id){const lvl=skillLevel(id),xp=skillXp(id),max=Number(skillDef(id)?.maxLevel||10);if(lvl>=max)return{lvl,xp,pct:100,next:null};const lo=SK_THRESH[Math.max(0,lvl-1)]||0,hi=SK_THRESH[lvl]||SK_THRESH.at(-1);return{lvl,xp,pct:clamp((xp-lo)/Math.max(1,hi-lo)*100),next:hi};}
