  function techniquesFor(actionId){return techniqueDefs().filter(t=>t.actionId===actionId);}
  function techniqueUnlocked(t,r){return !!t&&S().level>=Number(t.minLevel||1)&&skillLevel(actionDef(t.actionId)?.skillId)>=Number(t.minSkill||1)&&knowledgeLevel(r.knowledgeId)>=Number(t.minKnowledge||0);}
