  function generateContractOffers(force=false){cleanupOffers();const t=now();if(!force&&t-Number(S().lastContractRefresh||0)<12000)return;S().lastContractRefresh=t;const occupied=new Set([...S().contractOffers,...S().activeContracts].map(x=>x.contractId)),pool=blacksmithContracts().filter(d=>contractEligible(d)&&!occupied.has(d.id));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}while(S().contractOffers.length<4&&pool.length){const d=pool.shift();S().contractOffers.push({id:uid(),contractId:d.id,createdAt:t,expiresAt:t+90000});}}
